class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        if (nums1.length > nums2.length) {
            return findMedianSortedArrays(nums2, nums1);
        }

        int m = nums1.length;
        int n = nums2.length;
        int left = 0;
        int right = m;

        while (left <= right) {
            int i = left + (right - left) / 2;
            int j = (m + n + 1) / 2 - i;

            int maxLeft1 = (i == 0) ? Integer.MIN_VALUE : nums1[i - 1];
            int minRight1 = (i == m) ? Integer.MAX_VALUE : nums1[i];
            int maxLeft2 = (j == 0) ? Integer.MIN_VALUE : nums2[j - 1];
            int minRight2 = (j == n) ? Integer.MAX_VALUE : nums2[j];

            if (maxLeft1 <= minRight2 && maxLeft2 <= minRight1) {
                int maxLeft = Math.max(maxLeft1, maxLeft2);
                int minRight = Math.min(minRight1, minRight2);
                if ((m + n) % 2 == 1) {
                    return maxLeft;
                }
                return maxLeft / 2.0 + minRight / 2.0;
            }
            if (maxLeft1 > minRight2) {
                right = i - 1;
            } else {
                left = i + 1;
            }
        }

        return 0.0;
    }
}

class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int total = nums1.length + nums2.length;
        int leftRank = (total + 1) / 2;
        int rightRank = (total + 2) / 2;
        int leftValue = kth(nums1, 0, nums2, 0, leftRank);
        int rightValue = kth(nums1, 0, nums2, 0, rightRank);
        return leftValue / 2.0 + rightValue / 2.0;
    }

    private int kth(int[] a, int aStart, int[] b, int bStart, int k) {
        if (aStart >= a.length) {
            return b[bStart + k - 1];
        }
        if (bStart >= b.length) {
            return a[aStart + k - 1];
        }
        if (k == 1) {
            return Math.min(a[aStart], b[bStart]);
        }

        int half = k / 2;
        int aIndex = Math.min(aStart + half, a.length) - 1;
        int bIndex = Math.min(bStart + half, b.length) - 1;
        if (a[aIndex] <= b[bIndex]) {
            return kth(a, aIndex + 1, b, bStart, k - (aIndex - aStart + 1));
        }
        return kth(a, aStart, b, bIndex + 1, k - (bIndex - bStart + 1));
    }
}

class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int m = nums1.length;
        int n = nums2.length;
        int[] merged = new int[m + n];
        int i = 0;
        int j = 0;
        int k = 0;

        while (i < m && j < n) {
            if (nums1[i] <= nums2[j]) {
                merged[k++] = nums1[i++];
            } else {
                merged[k++] = nums2[j++];
            }
        }
        while (i < m) {
            merged[k++] = nums1[i++];
        }
        while (j < n) {
            merged[k++] = nums2[j++];
        }

        int total = m + n;
        if (total % 2 == 1) {
            return merged[total / 2];
        }
        return merged[total / 2 - 1] / 2.0 + merged[total / 2] / 2.0;
    }
}

class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        int m = nums1.length;
        int n = nums2.length;
        int total = m + n;
        int target = total / 2;
        int i = 0;
        int j = 0;
        int previous = 0;
        int current = 0;

        for (int count = 0; count <= target; count++) {
            previous = current;
            if (i < m && (j >= n || nums1[i] <= nums2[j])) {
                current = nums1[i++];
            } else {
                current = nums2[j++];
            }
        }

        if (total % 2 == 1) {
            return current;
        }
        return previous / 2.0 + current / 2.0;
    }
}
